def evolved_p89(x, N, rank, world_size, num_devices,
                 cores_per_device, xm, torch, num_nodes=1):
    # popcount via integer arithmetic
    idx = torch.arange(N, device=x.device).to(torch.int32)
    pc = torch.zeros_like(idx)
    r = idx
    for b in range(7):
        pc = pc + (r - (r // 2) * 2)
        r = r // 2
    return pc.to(x.dtype)

def evolved_p89(x, N, rank, world_size, num_devices,
                 cores_per_device, xm, torch, num_nodes=1):
    # popcount table built in python, placed on device
    vals = [bin(i).count("1") for i in range(N)]
    return torch.tensor(vals, device=x.device).to(x.dtype)
